// Physical hardware model generated by hardware_model.py; see that module for the facts.
import modelData from "./data/hardware-model.json";

interface ModelSlot {
  id: string;
  accepts: string[];
  srsim?: string | number;
  types?: string[];
  fixed?: string;
}

/** A physical card that SR-SIM provisions as a shared card type, e.g. the 2-port 100GE CFP IMM as imm-2pac-fp3. */
export interface CardProduct {
  name: string;
  description: string;
  /** Per built-in MDA slot (1, 2, ...), the MDA types it can be provisioned with. */
  mdas: string[][];
}

interface ModelPart {
  kind: string;
  slots?: ModelSlot[];
  occupies?: string[];
  sfm?: string[];
  label?: string;
  description?: string;
  products?: CardProduct[];
}

interface ModelChassis {
  slots: ModelSlot[];
  exclusive?: string[][];
  integrated?: string;
  /** MDA types a card takes in this chassis, where the chassis has its own physical versions of its MDAs. */
  card_mdas?: Record<string, string[]>;
}

export interface HardwareIssue {
  code: string;
  path: string;
  message: string;
}

type Item = Record<string, unknown>;

const parts = modelData.parts as Record<string, ModelPart>;
const chassisModels = modelData.chassis as Record<string, ModelChassis>;

const items = (value: unknown): Item[] =>
  Array.isArray(value) ? value.filter((item): item is Item => typeof item === "object" && item !== null) : [];
const slotText = (value: unknown) => (value === undefined || value === null ? "" : String(value).trim());
const srsimSlots = (slots: ModelSlot[] = []) => slots.map((slot) => String(slot.srsim));

/** SR-SIM component slots for line cards; [] when the chassis is not modelled or is integrated. */
export function lineCardSlots(chassis: string): number[] {
  const model = chassisModels[chassis];
  if (!model || model.integrated) return [];
  return model.slots.flatMap((slot) => (typeof slot.srsim === "number" ? [slot.srsim] : []));
}

/** CPM slots of a multi-container chassis; [] when the chassis is not modelled or uses a CPM adapter. */
export function cpmSlots(chassis: string): string[] {
  const model = chassisModels[chassis];
  if (!model || model.integrated) return [];
  return model.slots.flatMap((slot) => (slot.accepts.includes("cpm") && slot.srsim !== undefined ? [String(slot.srsim)] : []));
}

/** The card SR-SIM runs as slot A of a single-container chassis; "" when there is none in the model. */
export function integratedCard(chassis: string | undefined): string {
  return chassisModels[chassis ?? ""]?.integrated ?? "";
}

/** XCM-style module slots that each take an XMA or an XIOM; [] for other cards and unknown ones. */
export function moduleSlots(cardType: string | undefined): number[] {
  const slots = parts[cardType ?? ""]?.slots ?? [];
  return slots.some((slot) => slot.accepts.includes("iom")) ? slots.map((slot) => Number(slot.srsim)) : [];
}

/** SR-SIM mda/xiom slots of a component card; [] when the model does not know the card. */
export function cardSlots(cardType: string | undefined): number[] {
  const part = parts[cardType ?? ""];
  if (!part || part.kind === "cma") return [];
  return (part.slots ?? []).flatMap((slot) => (typeof slot.srsim === "number" && slot.accepts.length ? [slot.srsim] : []));
}

/** Slot numbers a card has but cannot fill, e.g. the SAR-Hmc's MDA slot 4. */
export function emptySlots(cardType: string | undefined): number[] {
  return (parts[cardType ?? ""]?.slots ?? []).flatMap((slot) =>
    typeof slot.srsim === "number" && !slot.accepts.length ? [slot.srsim] : []
  );
}

/** The slots of a known card that can hold mdaType (built-in parts only fit their own slot). */
export function mdaSlotsFor(cardType: string | undefined, mdaType: string): number[] {
  const part = parts[cardType ?? ""];
  if (!part || part.kind === "cma") return [];
  const slots = part.slots ?? [];
  return slots.flatMap((slot) =>
    typeof slot.srsim === "number" && slot.accepts.length && !placementIssue(cardType ?? "", slots, slot, mdaType, "")
      ? [slot.srsim]
      : []
  );
}

/** MDA slots of an IOM; [] when the model does not know the IOM. */
export function iomMdaSlots(iomType: string | undefined): number[] {
  const part = parts[iomType ?? ""];
  return part?.kind === "iom" ? (part.slots ?? []).map((slot) => Number(slot.srsim)) : [];
}

/** A part of this type in slot of owner (a chassis or card with these slots) that cannot be there. */
function placementIssue(owner: string, slots: ModelSlot[], slot: ModelSlot, type: string, path: string): HardwareIssue | null {
  if (!type) return null;
  if (slot.fixed) {
    return type === slot.fixed
      ? null
      : { code: "fixed", path, message: `slot ${slot.srsim} of ${owner} has the built-in ${slot.fixed}, not ${type}` };
  }
  const homes = slots.filter((other) => other.fixed === type).map((other) => String(other.srsim));
  if (homes.length) {
    return { code: "built-in", path, message: `${type} is built into slot ${homes.join(", ")} of ${owner}, not slot ${slot.srsim}` };
  }
  if (slot.types?.length && !slot.types.includes(type)) {
    const fits = slots.filter((other) => other.types?.includes(type)).map((other) => String(other.srsim));
    if (fits.length) {
      return { code: "slot-type", path, message: `${type} fits slot ${fits.join(", ")} of ${owner}, not slot ${slot.srsim}` };
    }
    return { code: "slot-type", path, message: `slot ${slot.srsim} of ${owner} takes ${slot.types.join(", ")}, not ${type}` };
  }
  return null;
}

/** Items placed in the slots of a card: each needs an existing slot that can hold its type. */
function nestedIssues(part: ModelPart, partType: string, nested: Item[], path: string, code: string, what: string): HardwareIssue[] {
  const slots = (part.slots ?? []).filter((slot) => slot.accepts.length);
  const empty = srsimSlots((part.slots ?? []).filter((slot) => !slot.accepts.length));
  const names = srsimSlots(slots);
  const issues: HardwareIssue[] = [];
  for (const item of nested) {
    const slotValue = slotText(item.slot);
    if (!slotValue) continue;
    const slot = slots.find((candidate) => String(candidate.srsim) === slotValue);
    const itemPath = `${path}[${slotValue}]`;
    if (empty.includes(slotValue)) {
      issues.push({ code: "empty-slot", path: itemPath, message: `slot ${slotValue} of ${partType} takes no ${what}` });
      continue;
    }
    if (!slot) {
      issues.push({
        code,
        path: itemPath,
        message: `${partType} has ${what} slot${names.length > 1 ? "s" : ""} ${[...names].sort().join(", ")}, not ${slotValue}`
      });
      continue;
    }
    const issue = placementIssue(partType, slots, slot, String(item.type ?? ""), itemPath);
    if (issue) issues.push(issue);
  }
  return issues;
}

function moduleIssues(part: ModelPart, partType: string, component: Item, path: string): HardwareIssue[] {
  const issues: HardwareIssue[] = [];
  const what = (part.slots ?? []).some((slot) => slot.accepts.includes("iom")) ? "module" : "MDA";
  for (const key of ["mda", "xiom"] as const) {
    issues.push(...nestedIssues(part, partType, items(component[key]), `${path}.${key}`, "module-slot", what));
  }
  const direct = new Set(items(component.mda).map((item) => slotText(item.slot)));
  const shared = items(component.xiom)
    .map((item) => slotText(item.slot))
    .filter((slot) => slot && direct.has(slot))
    .sort();
  for (const slot of new Set(shared)) {
    issues.push({ code: "module-taken", path: `${path}.xiom[${slot}]`, message: `module slot ${slot} holds either an XMA or an IOM, not both` });
  }
  for (const xiom of items(component.xiom)) {
    const iomType = String(xiom.type ?? "");
    const iom = parts[iomType];
    if (iom?.kind !== "iom") continue;
    issues.push(...nestedIssues(iom, iomType, items(xiom.mda), `${path}.xiom[${slotText(xiom.slot)}].mda`, "mda-slot", "MDA"));
  }
  issues.push(...productIssues(part, partType, component, path));
  return issues;
}

const mdaTypesBySlot = (component: Item): Map<number, string> =>
  new Map(
    items(component.mda).flatMap((item) => {
      const slot = Number(slotText(item.slot));
      return Number.isInteger(slot) && slot > 0 && item.type ? [[slot, String(item.type)] as [number, string]] : [];
    })
  );

/** Physical cards provisioned as this card type; [] when the card type is a single product. */
export function cardProducts(cardType: string | undefined): CardProduct[] {
  return parts[cardType ?? ""]?.products ?? [];
}

/** Whether the product's built-in MDA slots take the component's MDAs. */
export function productFits(product: CardProduct, component: unknown): boolean {
  const mdas = mdaTypesBySlot(items([component])[0] ?? {});
  return [...mdas].every(([slot, type]) => slot <= product.mdas.length && product.mdas[slot - 1].includes(type));
}

/** The first product of the card whose built-in MDA slots take the component's MDAs. */
export function cardProductOf(cardType: string | undefined, component: unknown): CardProduct | undefined {
  return cardProducts(cardType).find((product) => productFits(product, component));
}

/** On a card shared by several physical products, the MDAs must be those of one product. */
function productIssues(part: ModelPart, partType: string, component: Item, path: string): HardwareIssue[] {
  const mdas = mdaTypesBySlot(component);
  if (!part.products?.length || !mdas.size || cardProductOf(partType, component)) return [];
  const combo = [...mdas].sort(([a], [b]) => a - b).map(([slot, type]) => `${type} in slot ${slot}`).join(", ");
  return [{ code: "product", path: `${path}.mda`, message: `no ${partType} has ${combo}` }];
}

/** The part's name, e.g. "CMA-7s Dual" for cma-7s-d; the provisioning string when it has none. */
function displayName(type: string): string {
  return parts[type]?.label || type;
}

function carrierFit(carrier: ModelPart, cpms: Item[], used: Set<string>): "fits" | "occupied" | "mismatch" {
  for (const cpm of cpms) {
    const slot = (carrier.slots ?? []).find((candidate) => String(candidate.srsim) === slotText(cpm.slot).toUpperCase());
    const type = String(cpm.type ?? "");
    if (!slot || (type && !(slot.types ?? []).includes(type))) return "mismatch";
  }
  return (carrier.occupies ?? []).some((slotId) => used.has(slotId)) ? "occupied" : "fits";
}

function cpmIssues(chassisId: string, chassis: ModelChassis, cpms: Item[], used: Map<string, string>): HardwareIssue[] {
  const carrierSlot = chassis.slots.find((slot) => slot.accepts.includes("cma"));
  if (!carrierSlot) {
    const cpmSlots = chassis.slots.filter((slot) => slot.accepts.includes("cpm"));
    const names = srsimSlots(cpmSlots);
    return cpms.flatMap((cpm) => {
      const slotValue = slotText(cpm.slot).toUpperCase();
      const slot = cpmSlots.find((candidate) => String(candidate.srsim) === slotValue);
      if (!slot) {
        return [{ code: "no-such-slot", path: slotValue, message: `${chassisId} has CPM slots ${[...names].sort().join(", ")}, not ${slotValue}` }];
      }
      const issue = placementIssue(chassisId, chassis.slots, slot, String(cpm.type ?? ""), slotValue);
      return issue ? [issue] : [];
    });
  }

  const carriers = (carrierSlot.types ?? []).map((type) => ({ type, part: parts[type] }));
  const fit = carriers.map(({ part }) => carrierFit(part, cpms, new Set(used.keys())));
  if (fit.includes("fits")) return [];
  const blocked = carriers.find((_, index) => fit[index] === "occupied");
  if (blocked) {
    const taken = (blocked.part.occupies ?? []).flatMap((slotId) => (used.has(slotId) ? [used.get(slotId) as string] : [])).join(", ");
    return [
      {
        code: "occupied",
        path: taken,
        message: `these CPMs need the ${displayName(blocked.type)}, which also takes line-card slot ${taken}`
      }
    ];
  }
  const options = carriers.map(({ type }) => displayName(type)).join("; ");
  return [{ code: "cpm-carrier", path: cpms.map((cpm) => slotText(cpm.slot)).join(","), message: `no CPM adapter fits these CPMs (${options})` }];
}

/** Problems that make a component list impossible in hardware; [] for chassis without a model. */
function sfmIssues(all: Item[], sfm: string): HardwareIssue[] {
  return all.flatMap((item) => {
    const type = String(item.type ?? "");
    const allowed = parts[type]?.sfm ?? [];
    return sfm && allowed.length && !allowed.includes(sfm)
      ? [{ code: "sfm", path: slotText(item.slot), message: `${type} works only with ${allowed.join(", ")}, not ${sfm}` }]
      : [];
  });
}

export function hardwareIssues(chassisId: string, components: unknown[], sfm = ""): HardwareIssue[] {
  const chassis = chassisModels[chassisId.trim().toLowerCase()];
  if (!chassis) return [];
  const all = items(components);

  if (chassis.integrated) {
    const card = parts[chassis.integrated];
    const slot = chassis.slots.find((candidate) => candidate.srsim === "A") as ModelSlot;
    return all.flatMap((component) => {
      const issue = placementIssue(chassisId, chassis.slots, slot, String(component.type ?? ""), "A");
      return [...(issue ? [issue] : []), ...moduleIssues(card, chassis.integrated as string, component, "A")];
    });
  }

  const issues: HardwareIssue[] = [];
  const lineSlots = new Map(
    chassis.slots.filter((slot) => slot.srsim !== undefined && !slot.accepts.includes("cpm")).map((slot) => [String(slot.srsim), slot])
  );
  const cpms = all.filter((item) => /^[A-Za-z]$/.test(slotText(item.slot)));
  const used = new Map<string, string>();
  const lineTypes = new Set<string>();
  for (const card of all.filter((item) => !cpms.includes(item))) {
    const slotValue = slotText(card.slot);
    const slot = lineSlots.get(slotValue);
    if (!slot) {
      issues.push({
        code: "no-such-slot",
        path: slotValue,
        message: `${chassisId} has line-card slot${lineSlots.size > 1 ? "s" : ""} ${[...lineSlots.keys()].join(", ")}, not ${slotValue || "(none)"}`
      });
      continue;
    }
    used.set(slot.id, slotValue);
    const type = String(card.type ?? "");
    const issue = placementIssue(chassisId, chassis.slots, slot, type, slotValue);
    if (issue) {
      issues.push(issue);
      continue;
    }
    // A built-in card is there even when the component leaves its type out.
    const partType = type || slot.fixed || "";
    const part = parts[partType];
    if (!part) continue;
    lineTypes.add(partType);
    if (!slot.accepts.includes(part.kind)) {
      issues.push({ code: "slot-kind", path: slotValue, message: `slot ${slotValue} takes ${slot.accepts.join("/")}, not ${partType}` });
      continue;
    }
    issues.push(...moduleIssues(part, partType, card, slotValue));
    const allowed = chassis.card_mdas?.[partType];
    for (const mda of allowed ? items(card.mda) : []) {
      const type = String(mda.type ?? "");
      if (type && !allowed?.includes(type)) {
        issues.push({ code: "chassis-mda", path: `${slotValue}.mda[${slotText(mda.slot)}]`, message: `the ${chassisId.trim().toLowerCase()} has no ${type} for its ${partType}` });
      }
    }
  }

  issues.push(...cpmIssues(chassisId, chassis, cpms, used));
  issues.push(...sfmIssues(all, sfm));
  for (const group of chassis.exclusive ?? []) {
    const mixed = group.filter((type) => lineTypes.has(type)).sort();
    if (mixed.length > 1) {
      issues.push({ code: "mixed-types", path: "", message: `${mixed.join(" and ")} cannot be installed in the same chassis` });
    }
  }
  return issues;
}

/** A CMA (CPM adapter) a chassis can take. */
export interface CpmCarrier {
  type: string;
  label: string;
  description: string;
  cpmTypes: string[];
  cpmSlots: string[];
  /** Line-card slots the adapter also takes, e.g. XCM slot 6 for the dual CMA-7s. */
  blocksLineSlots: number[];
}

export function cpmCarriers(chassisId: string): CpmCarrier[] {
  const chassis = chassisModels[chassisId];
  const carrierSlot = chassis?.slots.find((slot) => slot.accepts.includes("cma"));
  if (!chassis || !carrierSlot) return [];
  return (carrierSlot.types ?? []).map((type) => {
    const part = parts[type];
    const slots = part.slots ?? [];
    return {
      type,
      label: displayName(type),
      description: part.description ?? "",
      cpmTypes: [...new Set(slots.flatMap((slot) => slot.types ?? []))],
      cpmSlots: srsimSlots(slots),
      blocksLineSlots: chassis.slots.flatMap((slot) =>
        (part.occupies ?? []).includes(slot.id) && typeof slot.srsim === "number" ? [slot.srsim] : []
      )
    };
  });
}

/** The first adapter that fits the configured CPMs and line cards. */
export function fittingCarrier(chassisId: string, components: unknown[]): CpmCarrier | undefined {
  const all = items(components);
  const cpms = all.filter((item) => /^[A-Za-z]$/.test(slotText(item.slot)));
  const usedLineSlots = new Set(all.filter((item) => !cpms.includes(item)).map((item) => Number(slotText(item.slot))));
  return cpmCarriers(chassisId).find(
    (carrier) =>
      carrierFit(parts[carrier.type], cpms, new Set()) === "fits" &&
      !carrier.blocksLineSlots.some((slot) => usedLineSlots.has(slot))
  );
}
